   * `INTCON` chooses what counts. A zero compares against the level the pin had
   * last time, so any edge is an interrupt; a one compares against `DEFVAL`, so
   * the flag follows a condition rather than a transition. Either way the
   * matching bit lands in `INTF`, and `INTCAP` keeps the byte the port held
   * when it happened, for a sketch that needs to know what the pins were doing.
   */
  updateInputs(levels: readonly boolean[]): void {
    const ports = [0, 1] as const;
    const now = new Uint8Array(2);
    for (const port of ports) {
      for (let bit = 0; bit < 8; bit++) {
        const index = port * 8 + bit;
        const driven = this.isOutput(index);
        const high = driven
          ? ((this.sampled[port]! >> bit) & 1) === 1
          : levels[index] === true;
        if (high) now[port]! |= 1 << bit;
      }
    }
    if (!this.sampledOnce) {
      this.sampled[0] = now[0]!;
      this.sampled[1] = now[1]!;
      this.sampledOnce = true;
      return;
    }
    for (const port of ports) {
      const base = port * 8;
      const enabled = this.registers[GPINTEN_A + port]!;
      if (enabled === 0) {
        this.sampled[port] = now[port]!;
        continue;
      }
      const compares = this.registers[INTCON_A + port]!;
      const defval = this.registers[DEFVAL_A + port]!;
      const changed = (this.sampled[port]! ^ now[port]!) & enabled;
      let hit = 0;
      for (let bit = 0; bit < 8; bit++) {
        const mask = 1 << bit;
        if ((enabled & mask) === 0) continue;
        const matches = (compares & mask) !== 0 ? ((now[port]! ^ defval) & mask) !== 0 : (changed & mask) !== 0;
