So "wakes the sketch through INTA instead of polling" must mean: the sketch polls the *INTA pin* (a single digitalRead on D2) rather than polling the expander over I2C (Wire reads each loop). That's the meaningful distinction here: the interrupt pin turns 16 pins into one MCU pin to watch, and the sketch only talks I2C when the flag rises. That's honest and demonstrable; and the docs already explain that attachInterrupt is refused.

So the sketch:
```cpp
#include <Wire.h>

const byte EXPANDER = 0x20;
const byte IODIR_A = 0x00;
const byte GPINTEN_A = 0x04;
const byte INTCON_A = 0x08;
const byte GPPU_A = 0x0C;
const byte INTF_A = 0x0E;
const byte GPIO_A = 0x12;
const byte INTA = 2;

void writeRegister(byte reg, byte value) { ... }
byte readRegister(byte reg) { Wire.beginTransmission; Wire.write(reg); endTransmission(false)?; requestFrom(EXPANDER,1); return Wire.read(); }

void setup() {
  Serial.begin(9600);
  Wire.begin();
  pinMode(INTA, INPUT_PULLUP);
  writeRegister(IODIR_A, 0xFF);
  writeRegister(GPPU_A, 0x01);     // pull-up on PA0
  writeRegister(INTCON_A, 0x00);   // any change
  writeRegister(GPINTEN_A, 0x01);  // watch PA0
  Serial.println("watching PA0");
}

void loop() {
  if (digitalRead(INTA) == LOW) {
    byte flags = readRegister(INTF_A);   // read clears
    Serial.print("interrupt ");
    Serial.println(flags, HEX);
    // Reading GPIO also clears; we already cleared with INTF.
  }
  delay(20);
}
```

