/**
 * A clean path onto the hash router.
 *
 * The app routes on the hash so a bench is a link that survives a refresh on
 * static hosting (see `app/App.tsx`). That leaves one gap: a link written the
 * ordinary way, `/diagnostics`, arrives with an empty hash, and the router's
 * catch-all sends it to the picker. Folding the pathname into the hash before
 * the router mounts closes it without giving up the no-rewrite property --
 * the address becomes `/#/diagnostics` and the panel renders.
 *
 * Only the paths listed here are adopted: each one is a page someone might
 * paste as a link, and a host with no rewrite returns its own 404 for anything
 * else before this script runs at all.
 */
const CLEAN_PATHS = new Set(['/diagnostics']);

function adoptCleanPath(): void {
  const { pathname, search, hash } = window.location;
  const path = pathname.endsWith('/') && pathname !== '/' ? pathname.slice(0, -1) : pathname;
  if (hash !== '' || !CLEAN_PATHS.has(path)) return;
  window.history.replaceState(null, '', `/#${path}${search}`);
}

adoptCleanPath();
```

