+ * Only the paths named here are adopted, and only because each is a page worth
+ * pasting as a link. This runs after the host has already answered, so it can
+ * convert a request it can see but cannot rescue: a host without a rewrite rule
+ * returns its own 404 for a clean path before any of this code loads.
+ */
+const CLEAN_PATHS = new Set(['/diagnostics']);
+
+function adoptCleanPath(): void {
+  const { pathname, search, hash } = window.location;
+  const path = pathname.length > 1 && pathname.endsWith('/') ? pathname.slice(0, -1) : pathname;
+  if (hash !== '' || !CLEAN_PATHS.has(path)) return;
+  window.history.replaceState(null, '', `/#${path}${search}`);
+}
+
