import { Mcp23017 } from './mcp23017';

const IODIR_A = 0x00;
const GPINTEN_A = 0x04;
const DEFVAL_A = 0x06;
const INTCON_A = 0x08;
const INTF_A = 0x0e;
const INTCAP_A = 0x10;
const GPIO_A = 0x12;
const OLAT_A = 0x14;

function write(expander: Mcp23017, register: number, value: number): void {
  expander.receive(register, true);
  expander.receive(value, false);
}
function read(expander: Mcp23017, register: number): number {
  expander.receive(register, true);
  return expander.read(1)[0]!;
}
const levels = (...high: number[]): boolean[] =>
  Array.from({ length: 16 }, (_, index) => high.includes(index));

describe('probe', () => {
  it('reports what INTF/INTCAP do', () => {
    // 1. Does reading INTF release the interrupt output?
    const a = new Mcp23017();
    write(a, GPINTEN_A, 0x01);
    write(a, INTCON_A, 0x00);
    a.updateInputs(levels());
    a.updateInputs(levels(0));
    const before = a.interruptLevel(0);
    const flag = read(a, INTF_A);
    const after = a.interruptLevel(0);

    // 2. What does INTCAP say about output pins in the same port?
    const b = new Mcp23017();
    write(b, IODIR_A, 0b1111_0000); // PA4..PA7 driven
    write(b, OLAT_A, 0b1111_0000); // ... high
    write(b, GPINTEN_A, 0x01); // watch PA0 only
    b.updateInputs(levels());
    b.updateInputs(levels(0));
    const capture = read(b, INTCAP_A);

    // 3. Can DEFVAL flag a pin the chip is driving?
    const c = new Mcp23017();
    write(c, IODIR_A, 0b1111_0000); // PA4..PA7 driven
    write(c, GPINTEN_A, 0b1111_0000); // watch the driven pins
    write(c, INTCON_A, 0b1111_0000); // level mode
    write(c, DEFVAL_A, 0b1111_0000); // ... expecting them high
    c.updateInputs(levels());
    const outputFlag = read(c, INTF_A);

    console.log(
      `\n---PROBE---\nINTF read: flag=${flag} asserted-before=${String(before)} asserted-after=${String(after)}\nINTCAP with high outputs: 0b${capture.toString(2).padStart(8, '0')}\nDEFVAL flag on driven pins: 0b${outputFlag.toString(2).padStart(8, '0')}\nGPIO read (control): 0b${read(b, GPIO_A).toString(2).padStart(8, '0')}\n---END---`,
    );
  });
});
"}}


